-- Animal Kingdom Concrete Gap Repair V2. Manual Studio Command Bar execution only.
local Workspace=game:GetService("Workspace")
local ServerStorage=game:GetService("ServerStorage")
local MARKER="AnimalKingdomConcreteGapRepairV2"
local ROLLBACK_NAME="AnimalKingdomConcreteGapRepairV2Rollback"
local BIOMES={"Meadow","Forest","Jungle","Desert","Snow","Volcano","Ocean","AncientRuins","MagicalForest","Sky","Prehistoric","Mythical"}
if Workspace:GetAttribute(MARKER)==true then warn(MARKER.." already applied")return end
if ServerStorage:FindFirstChild(ROLLBACK_NAME)then error("Stale V2 rollback folder exists; no changes made")end
local root=Workspace:FindFirstChild("BiomeEnvironments")local grass=Workspace:FindFirstChild("GrassFloor")local concreteRoot=Workspace:FindFirstChild("AnimalKingdomConcreteGround")
if not root or not grass or not grass:IsA("BasePart")or not concreteRoot then error("Required biome, GrassFloor, or V1 concrete hierarchy missing")end

local function topY(p)local best=-math.huge for _,x in ipairs({-1,1})do for _,y in ipairs({-1,1})do for _,z in ipairs({-1,1})do best=math.max(best,p.CFrame:PointToWorldSpace(Vector3.new(x*p.Size.X*.5,y*p.Size.Y*.5,z*p.Size.Z*.5)).Y)end end end return best end
local function insideXZ(p,q,t)local v=p.CFrame:PointToObjectSpace(q);t=t or 0 return math.abs(v.X)<=p.Size.X*.5+t and math.abs(v.Z)<=p.Size.Z*.5+t end
local function median(a)table.sort(a)local n=#a;if n==0 then return nil end return n%2==1 and a[(n+1)/2]or(a[n/2]+a[n/2+1])*.5 end
local EXCLUDE={"trees","rocks","decor","plants","transition","presentation","label","future","marker","helper","debug","path","crystal"}
local function excluded(i)local p=i while p and p~=Workspace do local n=p.Name:lower()for _,w in ipairs(EXCLUDE)do if n:find(w,1,true)then return true end end p=p.Parent end return false end
local function treeFolder(env)local s=env:FindFirstChild("Scenery")return s and s:FindFirstChild("Trees")end
local function supports(env)local all,trees,shake,ys={},{},{},{}local f=treeFolder(env)if not f then return nil end for _,m in ipairs(f:GetChildren())do if m:IsA("Model")then local cf,sz=m:GetBoundingBox()local q=Vector3.new(cf.Position.X,cf.Position.Y-sz.Y*.5,cf.Position.Z)table.insert(all,q);table.insert(trees,q);table.insert(ys,q.Y)end end for _,p in ipairs(env:GetDescendants())do if p:IsA("BasePart")and p.Name:lower():find("futureshakeablespot",1,true)then table.insert(all,p.Position);table.insert(shake,p.Position)end end return{all=all,trees=trees,shake=shake,medianY=median(ys)}end
local function eligible(p,y)if not p:IsA("BasePart")or not p.Anchored or p.Transparency>=1 or excluded(p)then return false end return math.abs(p.CFrame.UpVector:Dot(Vector3.yAxis))>=.88 and p.Size.X*p.Size.Z>=100 and math.abs(topY(p)-y)<=18 end
local function resolveFloor(b)
 local env=root:FindFirstChild(b.."Environment")local s=env and supports(env)if not env or not s or #s.trees==0 then return nil,"support data missing"end
 local pool,seen={},{}for _,p in ipairs(env:GetDescendants())do if p:IsA("BasePart")then table.insert(pool,p);seen[p]=true end end local key=b:lower()for _,p in ipairs(Workspace:GetDescendants())do if p:IsA("BasePart")and not seen[p]then local path=p:GetFullName():lower()local n=p.Name:lower()if path:find(key,1,true)and(n:find("floor",1,true)or n:find("ground",1,true)or n:find("plot",1,true)or path:find("biomeplot",1,true))then table.insert(pool,p)end end end
 local candidates={}for _,p in ipairs(pool)do if eligible(p,s.medianY)then local count=0 for _,q in ipairs(s.all)do if insideXZ(p,q,2)then count=count+1 end end local coverage=count/math.max(1,#s.all)local n=p.Name:lower()local nameScore=(n:find("floor",1,true)or n:find("plot",1,true))and 12 or(n:find("ground",1,true)and 4 or 0)if n:find("separator",1,true)or n=="grassfloor"or n:find("baseplate",1,true)then nameScore=nameScore-35 end local score=coverage*100+(1-math.min(1,math.abs(topY(p)-s.medianY)/18))*8+nameScore;table.insert(candidates,{part=p,score=score})end end table.sort(candidates,function(a,z)return a.score>z.score end)
 local chosen,covered={},{}for _,c in ipairs(candidates)do local adds=false for i,q in ipairs(s.all)do if not covered[i]and insideXZ(c.part,q,2)then adds=true break end end if adds then table.insert(chosen,c.part)for i,q in ipairs(s.all)do if insideXZ(c.part,q,2)then covered[i]=true end end end local n=0 for _ in pairs(covered)do n=n+1 end if n==#s.all then break end end local n=0 for _ in pairs(covered)do n=n+1 end local coverage=n/math.max(1,#s.all)
 if #chosen==0 or coverage<.9 then return nil,"coverage="..coverage end for _,q in ipairs(s.trees)do local ok=false for _,p in ipairs(chosen)do if insideXZ(p,q,3)then ok=true break end end if not ok then return nil,"tree outside resolved floor"end end
 for _,p in ipairs(chosen)do print("AK_CONCRETE_V2_BIOME_FLOOR biome="..b.." path="..p:GetFullName().." size="..tostring(p.Size).." topY="..topY(p).." supportCoverage="..coverage)end return{biome=b,parts=chosen,coverage=coverage}
end

print("[1/7] Resolving exact biome floor footprints")
local floors={}local resolved={}local floorState={}for _,b in ipairs(BIOMES)do local r,e=resolveFloor(b)if not r then error("V2 floor resolver failed for "..b..": "..tostring(e))end resolved[b]=r for _,p in ipairs(r.parts)do table.insert(floors,p);floorState[p]={CFrame=p.CFrame,Size=p.Size,Material=p.Material,Color=p.Color}end end
local concreteParts={}for _,p in ipairs(concreteRoot:GetDescendants())do if p:IsA("BasePart")then table.insert(concreteParts,p)end end if concreteRoot:IsA("BasePart")then table.insert(concreteParts,concreteRoot)end if #concreteParts==0 then error("No existing V1 concrete BaseParts found")end
local sample=concreteParts[1]local commonTop=median((function()local a={}for _,p in ipairs(concreteParts)do table.insert(a,topY(p))end return a end)())local thickness=sample.Size.Y
local appearance={Material=sample.Material,Color=sample.Color,Reflectance=sample.Reflectance,Transparency=sample.Transparency,CastShadow=sample.CastShadow}

print("[2/7] Auditing live V1 concrete coverage")
local mapHalfX,mapHalfZ=grass.Size.X*.5,grass.Size.Z*.5 local _,mapYaw,_=grass.CFrame:ToOrientation()
local function corners(p)local a={}for _,x in ipairs({-1,1})do for _,z in ipairs({-1,1})do table.insert(a,p.CFrame:PointToWorldSpace(Vector3.new(x*p.Size.X*.5,0,z*p.Size.Z*.5)))end end return a end
for _,p in ipairs(floors)do for _,q in ipairs(corners(p))do if not insideXZ(grass,q,.5)then error("Resolved biome floor exceeds GrassFloor boundary")end end end
local function localBounds(p)local x0,x1,z0,z1=math.huge,-math.huge,math.huge,-math.huge for _,q in ipairs(corners(p))do local v=grass.CFrame:PointToObjectSpace(q);x0=math.min(x0,v.X);x1=math.max(x1,v.X);z0=math.min(z0,v.Z);z1=math.max(z1,v.Z)end return x0,x1,z0,z1 end
local function sat(x0,x1,z0,z1,p,pad)local center=grass.CFrame:PointToWorldSpace(Vector3.new((x0+x1)*.5,0,(z0+z1)*.5))local ax,az=grass.CFrame.RightVector,grass.CFrame.LookVector local bx,bz=p.CFrame.RightVector,p.CFrame.LookVector local ahx,ahz=(x1-x0)*.5,(z1-z0)*.5 local bhx,bhz=p.Size.X*.5+pad,p.Size.Z*.5+pad local d=p.Position-center for _,axis in ipairs({ax,az,bx,bz})do local distance=math.abs(d:Dot(axis))local ra=ahx*math.abs(ax:Dot(axis))+ahz*math.abs(az:Dot(axis))local rb=bhx*math.abs(bx:Dot(axis))+bhz*math.abs(bz:Dot(axis))if distance>=ra+rb then return false end end return true end
local function pointCovered(list,world,tolerance)for _,p in ipairs(list)do if insideXZ(p,world,tolerance or 0)and math.abs(topY(p)-commonTop)<.15 then return true end end return false end

print("[3/7] High-resolution missing-ground scan")
local resolution=1 local xs,zs={},{}local x=-mapHalfX while x<mapHalfX do table.insert(xs,x);x=math.min(mapHalfX,x+resolution)end table.insert(xs,mapHalfX)local z=-mapHalfZ while z<mapHalfZ do table.insert(zs,z);z=math.min(mapHalfZ,z+resolution)end table.insert(zs,mapHalfZ)
local edgeTolerance=.04 for _,p in ipairs(floors)do local x0,x1,z0,z1=localBounds(p)table.insert(xs,math.max(-mapHalfX,x0-edgeTolerance));table.insert(xs,math.min(mapHalfX,x1+edgeTolerance));table.insert(zs,math.max(-mapHalfZ,z0-edgeTolerance));table.insert(zs,math.min(mapHalfZ,z1+edgeTolerance))end
local function dedupe(a)table.sort(a)local out={}for _,v in ipairs(a)do if #out==0 or math.abs(v-out[#out])>.001 then table.insert(out,v)end end return out end xs=dedupe(xs);zs=dedupe(zs)
local nx,nz=#xs-1,#zs-1 local missing={}local biomeCells,existingCells,missingCells=0,0,0
for iz=1,nz do missing[iz]={}for ix=1,nx do local x0,x1,z0,z1=xs[ix],xs[ix+1],zs[iz],zs[iz+1]local biome=false for _,p in ipairs(floors)do if sat(x0,x1,z0,z1,p,edgeTolerance)then biome=true break end end local center=grass.CFrame:PointToWorldSpace(Vector3.new((x0+x1)*.5,0,(z0+z1)*.5))local existing=not biome and pointCovered(concreteParts,center,.02)or false local gap=not biome and not existing;missing[iz][ix]=gap;if biome then biomeCells=biomeCells+1 elseif existing then existingCells=existingCells+1 elseif gap then missingCells=missingCells+1 end end end

print("[4/7] Finding connected concrete gaps")
local visited={}for iz=1,nz do visited[iz]={}end local regionsInfo={}local dirs={{1,0},{-1,0},{0,1},{0,-1}}
for iz=1,nz do for ix=1,nx do if missing[iz][ix]and not visited[iz][ix]then local queue={{ix,iz}}visited[iz][ix]=true local head=1 local cells=0 local minX,maxX,minZ,maxZ=math.huge,-math.huge,math.huge,-math.huge while head<=#queue do local c=queue[head]head=head+1 local cx,cz=c[1],c[2];cells=cells+1;minX=math.min(minX,xs[cx]);maxX=math.max(maxX,xs[cx+1]);minZ=math.min(minZ,zs[cz]);maxZ=math.max(maxZ,zs[cz+1])for _,d in ipairs(dirs)do local xx,zz=cx+d[1],cz+d[2]if xx>=1 and xx<=nx and zz>=1 and zz<=nz and missing[zz][xx]and not visited[zz][xx]then visited[zz][xx]=true;table.insert(queue,{xx,zz})end end end table.insert(regionsInfo,{cells=cells,minX=minX,maxX=maxX,minZ=minZ,maxZ=maxZ})end end end
for i,r in ipairs(regionsInfo)do local center=grass.CFrame:PointToWorldSpace(Vector3.new((r.minX+r.maxX)*.5,0,(r.minZ+r.maxZ)*.5))local near={}for b,data in pairs(resolved)do local best=math.huge for _,p in ipairs(data.parts)do best=math.min(best,(Vector3.new(center.X,0,center.Z)-Vector3.new(p.Position.X,0,p.Position.Z)).Magnitude)end table.insert(near,{b=b,d=best})end table.sort(near,function(a,z)return a.d<z.d end)print("AK_CONCRETE_GAP")print("region="..i)print("cells="..r.cells)print("area="..((r.maxX-r.minX)*(r.maxZ-r.minZ)))print("minX="..r.minX)print("maxX="..r.maxX)print("minZ="..r.minZ)print("maxZ="..r.maxZ)print("nearestBiomeA="..near[1].b)print("nearestBiomeB="..near[2].b)end

print("[5/7] Merging and creating repair rectangles")
local used={}for iz=1,nz do used[iz]={}end local rectangles={}
for iz=1,nz do for ix=1,nx do if missing[iz][ix]and not used[iz][ix]then local x2=ix while x2<nx and missing[iz][x2+1]and not used[iz][x2+1]do x2=x2+1 end local z2=iz local extend=true while extend and z2<nz do for xx=ix,x2 do if not missing[z2+1][xx]or used[z2+1][xx]then extend=false break end end if extend then z2=z2+1 end end for zz=iz,z2 do for xx=ix,x2 do used[zz][xx]=true end end table.insert(rectangles,{x0=xs[ix],x1=xs[x2+1],z0=zs[iz],z1=zs[z2+1]})end end end
local rollback=Instance.new("Folder")rollback.Name=ROLLBACK_NAME;rollback:SetAttribute("CreatedPartsPlanned",#rectangles);rollback.Parent=ServerStorage
local repair=Instance.new("Folder")repair.Name="GapRepairV2"local created={}local ok,err=pcall(function()for i,r in ipairs(rectangles)do local center=grass.CFrame:PointToWorldSpace(Vector3.new((r.x0+r.x1)*.5,0,(r.z0+r.z1)*.5))local p=Instance.new("Part")p.Name="GapRepair_"..string.format("%03d",i)p.Anchored=true;p.CanCollide=true;p.CanTouch=true;p.CanQuery=true;p.CastShadow=appearance.CastShadow;p.Material=appearance.Material;p.Color=appearance.Color;p.Reflectance=appearance.Reflectance;p.Transparency=appearance.Transparency;p.Size=Vector3.new(r.x1-r.x0,thickness,r.z1-r.z0);p.CFrame=CFrame.new(center.X,commonTop-thickness*.5,center.Z)*CFrame.Angles(0,mapYaw,0);p.Parent=repair;table.insert(created,p)end repair.Parent=concreteRoot end)
local function rollbackAll(message)if repair.Parent then repair:Destroy()end rollback:Destroy()Workspace:SetAttribute(MARKER,nil)error("Concrete Gap Repair V2 rollback: "..tostring(message))end
if not ok then rollbackAll(err)end

print("[6/7] Post-repair geometry coverage validation")
local allConcrete={}for _,p in ipairs(concreteRoot:GetDescendants())do if p:IsA("BasePart")then table.insert(allConcrete,p)end end local uncovered=0
for iz=1,nz do for ix=1,nx do local x0,x1,z0,z1=xs[ix],xs[ix+1],zs[iz],zs[iz+1]local biome=false for _,p in ipairs(floors)do if sat(x0,x1,z0,z1,p,edgeTolerance)then biome=true break end end if not biome then local center=grass.CFrame:PointToWorldSpace(Vector3.new((x0+x1)*.5,0,(z0+z1)*.5))if not pointCovered(allConcrete,center,.02)then uncovered=uncovered+1;if uncovered<=25 then print("AK_CONCRETE_UNCOVERED")print("position="..tostring(center))print("nearestBiome=UNRESOLVED")print("reason=no concrete footprint")end end end end end
local intrusions=0 local levelMismatch=0 for _,p in ipairs(created)do if math.abs(topY(p)-commonTop)>.02 then levelMismatch=levelMismatch+1 end local x0,x1,z0,z1=localBounds(p)for _,f in ipairs(floors)do if sat(x0,x1,z0,z1,f,-.1)then intrusions=intrusions+1 end end end

print("[7/7] Raycast surface leak validation")
local rayParams=RaycastParams.new()rayParams.FilterType=Enum.RaycastFilterType.Include local include={grass,concreteRoot}for _,p in ipairs(floors)do table.insert(include,p)end rayParams.FilterDescendantsInstances=include local samples,biomeSamples,concreteSamples,grassLeaks=0,0,0,0
for z=-mapHalfZ+.5,mapHalfZ-.5,2 do for x=-mapHalfX+.5,mapHalfX-.5,2 do local world=grass.CFrame:PointToWorldSpace(Vector3.new(x,0,z))local biome=false for _,p in ipairs(floors)do if insideXZ(p,world,edgeTolerance)then biome=true break end end samples=samples+1;if biome then biomeSamples=biomeSamples+1 else local hit=Workspace:Raycast(Vector3.new(world.X,commonTop+100,world.Z),Vector3.new(0,-200,0),rayParams)if hit and hit.Instance:IsDescendantOf(concreteRoot)then concreteSamples=concreteSamples+1 else grassLeaks=grassLeaks+1 end end end end
print("AK_CONCRETE_SURFACE_SCAN")print("samples="..samples)print("biomeSamples="..biomeSamples)print("concreteSamples="..concreteSamples)print("grassLeaks="..grassLeaks)
for p,s in pairs(floorState)do if p.CFrame~=s.CFrame or p.Size~=s.Size or p.Material~=s.Material or p.Color~=s.Color then rollbackAll("Biome floor changed: "..p:GetFullName())end end
if uncovered>0 or grassLeaks>0 or intrusions>0 or levelMismatch>0 then rollbackAll("Validation failed uncovered="..uncovered.." grassLeaks="..grassLeaks.." intrusions="..intrusions.." levels="..levelMismatch)end
Workspace:SetAttribute(MARKER,true)
print("ANIMAL KINGDOM CONCRETE GAP REPAIR V2 COMPLETE")print("Biome floors resolved: 12/12")print("Existing V1 concrete preserved: YES")print("Repair parts added: "..#created)print("Remaining missing concrete cells: 0")print("GrassFloor leaks at non-biome locations: 0")print("Concrete/biome intrusion >0.1 studs: 0")print("Concrete surface level mismatches: 0")print("Tree changes: 0")print("Biome floor changes: 0")print("Gameplay changes: 0")print("Rollback: ServerStorage."..ROLLBACK_NAME)print("Failures: 0")
